<?php
/** Secure first-run setup wizard. @package AIContentStudio */
if(!defined('ABSPATH')){exit;}
final class AICS_Setup_Wizard_Page{
	private const AJAX='aics_setup_wizard';
	public static function register():void{add_action('admin_init',array(self::class,'maybe_redirect'));add_action('wp_ajax_'.self::AJAX,array(self::class,'ajax'));add_action('admin_post_aics_dismiss_setup',array(self::class,'dismiss_banner'));}
	private static function guard():void{if(!current_user_can(\AIContentStudio\Core\Permissions::manage())){wp_die(esc_html__('You do not have permission to access this page.','ai-content-studio'));}}
	public static function maybe_redirect():void{$flag=get_option(AICS_Setup_Wizard_State_Service::REDIRECT_OPTION,false);if(false===$flag){return;}delete_option(AICS_Setup_Wizard_State_Service::REDIRECT_OPTION);if(!current_user_can(\AIContentStudio\Core\Permissions::manage())||is_network_admin()||wp_doing_ajax()||wp_doing_cron()||(defined('REST_REQUEST')&&REST_REQUEST)||(defined('WP_CLI')&&WP_CLI)||isset($_GET['activate-multi'])){return;}wp_safe_redirect(admin_url('admin.php?page=aics-setup'));exit;}
	public static function dismiss_banner():void{self::guard();check_admin_referer('aics_dismiss_setup');AICS_Setup_Wizard_State_Service::dismiss();wp_safe_redirect(admin_url('admin.php?page=ai-content-studio'));exit;}
	public static function render():void{self::guard();?><div class="wrap aics-admin-wrap aics-setup-page"><header class="aics-page-header"><h1><?php esc_html_e('Setup AI Content Studio','ai-content-studio');?></h1><p><?php esc_html_e('Connect your provider and prepare your content workspace.','ai-content-studio');?></p></header><?php self::root();?></div><?php }
	public static function render_embedded():void{self::guard();self::root();}
	private static function root():void{?><div id="aics-setup-wizard" class="aics-wizard-shell" data-endpoint="<?php echo esc_url(admin_url('admin-ajax.php'));?>" data-action="<?php echo esc_attr(self::AJAX);?>" data-nonce="<?php echo esc_attr(wp_create_nonce(self::AJAX));?>"><?php echo self::html();// phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></div><noscript><div class="notice notice-error"><p><?php esc_html_e('JavaScript is required for this wizard. Saved settings remain unchanged.','ai-content-studio');?></p></div></noscript><?php }
	public static function ajax():void{self::guard();check_ajax_referer(self::AJAX,'nonce');$op=sanitize_key((string)($_POST['operation']??'render'));if(!in_array($op,array('render','navigate','start','test_provider','continue_provider','test_images','save_images','skip_images','save_seo','save_defaults','complete','dismiss','restart'),true)){wp_send_json_error(array('message'=>__('Unsupported setup action.','ai-content-studio')),400);}$notice='';
		if('navigate'===$op){$step=sanitize_key((string)($_POST['step']??''));if(!AICS_Setup_Wizard_State_Service::can_open($step)){wp_send_json_error(array('message'=>__('That setup step is not available yet.','ai-content-studio')),409);}AICS_Setup_Wizard_State_Service::save(array('setup_current_step'=>$step));}
		elseif('start'===$op){AICS_Setup_Wizard_State_Service::advance('welcome','ai-provider');}
		elseif('test_provider'===$op){self::save_provider();$r=(new AICS_OpenAI_Provider())->test_connection();if(empty($r['success'])){wp_send_json_error(array('message'=>$r['message']),400);}AICS_Setup_Wizard_State_Service::save(array('provider_test'=>array('provider'=>'openai','model'=>AICS_Settings::get_openai_model(),'tested_at'=>current_time('mysql',true))));$notice=__('Connection successful. Text generation is ready.','ai-content-studio');}
		elseif('continue_provider'===$op){self::save_provider();if(!AICS_Setup_Wizard_State_Service::provider_ready()){wp_send_json_error(array('message'=>__('Test the saved connection before continuing.','ai-content-studio')),409);}AICS_Setup_Wizard_State_Service::advance('ai-provider','featured-images');}
		elseif('save_images'===$op){$old=AICS_Featured_Image_Settings::get_effective();$input=array('enabled'=>!empty($_POST['enabled']),'provider'=>sanitize_key((string)($_POST['provider']??$old['provider'])),'model'=>sanitize_text_field((string)($_POST['model']??$old['model'])),'visual_style'=>sanitize_key((string)($_POST['visual_style']??$old['visual_style'])),'aspect_ratio'=>sanitize_key((string)($_POST['aspect_ratio']??$old['aspect_ratio'])),'quality'=>sanitize_key((string)($_POST['quality']??$old['quality'])),'output_format'=>sanitize_key((string)($_POST['output_format']??$old['output_format'])));$r=AICS_Featured_Image_Settings::update($input);if(is_wp_error($r)){wp_send_json_error(array('message'=>$r->get_error_message()),400);}AICS_Setup_Wizard_State_Service::advance('featured-images','seo-integration',empty($input['enabled']));}
		elseif('test_images'===$op){$settings=AICS_Featured_Image_Settings::get_effective();$settings['enabled']=!empty($_POST['enabled']);foreach(array('provider','model','visual_style','aspect_ratio','quality','output_format') as $key){if(isset($_POST[$key])&&is_scalar($_POST[$key])){$settings[$key]=sanitize_text_field(wp_unslash((string)$_POST[$key]));}}$valid=AICS_Featured_Image_Settings::validate($settings);if(is_wp_error($valid)||empty($settings['enabled'])){wp_send_json_error(array('message'=>is_wp_error($valid)?$valid->get_error_message():__('Enable featured images before testing.','ai-content-studio')),400);}$result=(new AICS_Featured_Image_Generation_Service())->generate_with_settings(array('title'=>__('Modern content strategy','ai-content-studio'),'topic_keyword'=>__('content strategy','ai-content-studio'),'business_context'=>__('A small business website','ai-content-studio')),$settings);$file=$result->get_temporary_file();$clean=$file?$file->cleanup():true;if(!$result->is_success()||!$clean){wp_send_json_error(array('message'=>$result->is_success()?__('The temporary test image could not be removed.','ai-content-studio'):$result->get_message()),400);}$notice=__('Image generation is ready. The temporary test file was deleted.','ai-content-studio');}
		elseif('skip_images'===$op){AICS_Setup_Wizard_State_Service::advance('featured-images','seo-integration',true);}
		elseif('save_seo'===$op){$target=sanitize_key((string)($_POST['seo_target']??'auto'));if(!isset(AICS_SEO_Configuration::target_labels()[$target])){wp_send_json_error(array('message'=>__('Select a supported SEO target.','ai-content-studio')),400);}AICS_Setup_Wizard_State_Service::save(array('seo_target'=>$target));AICS_Setup_Wizard_State_Service::advance('seo-integration','content-defaults');}
		elseif('save_defaults'===$op){$d=array('tone'=>sanitize_key((string)($_POST['tone']??'')),'article_length'=>sanitize_key((string)($_POST['article_length']??'')),'content_format'=>sanitize_key((string)($_POST['content_format']??'')),'post_status'=>'draft');if(!in_array($d['tone'],array('professional','friendly','informative','conversational'),true)||!in_array($d['article_length'],array('short','medium','long'),true)||!in_array($d['content_format'],array('plain','how-to','listicle'),true)){wp_send_json_error(array('message'=>__('One or more defaults are invalid.','ai-content-studio')),400);}AICS_Setup_Wizard_State_Service::save(array('defaults'=>$d));AICS_Setup_Wizard_State_Service::advance('content-defaults','finish');}
		elseif('complete'===$op){if(!AICS_Setup_Wizard_State_Service::complete()){wp_send_json_error(array('message'=>__('A tested AI connection is required.','ai-content-studio')),409);}$notice=__('Your workspace is ready.','ai-content-studio');}
		elseif('dismiss'===$op){AICS_Setup_Wizard_State_Service::dismiss();}
		elseif('restart'===$op){AICS_Setup_Wizard_State_Service::restart();}
		wp_send_json_success(array('html'=>self::html(),'step'=>AICS_Setup_Wizard_State_Service::state()['setup_current_step'],'notice'=>array('message'=>$notice)));
	}
	private static function save_provider():void{$model=sanitize_text_field((string)($_POST['openai_model']??AICS_Settings::get_openai_model()));$key=isset($_POST['openai_api_key'])?wp_unslash((string)$_POST['openai_api_key']):'';$changed=AICS_Settings::get_openai_model()!==$model||''!==trim($key);$r=AICS_Settings::update(array('openai_model'=>$model,'openai_api_key'=>$key));if(is_wp_error($r)){wp_send_json_error(array('message'=>$r->get_error_message()),400);}if($changed){AICS_Setup_Wizard_State_Service::save(array('provider_test'=>array()));}}
	private static function html():string{ob_start();$s=AICS_Setup_Wizard_State_Service::state();$step=$s['setup_current_step'];$labels=array('welcome'=>__('Welcome','ai-content-studio'),'ai-provider'=>__('AI Provider','ai-content-studio'),'featured-images'=>__('Images','ai-content-studio'),'seo-integration'=>__('SEO','ai-content-studio'),'content-defaults'=>__('Defaults','ai-content-studio'),'finish'=>__('Finish','ai-content-studio'));$active=array_search($step,AICS_Setup_Wizard_State_Service::STEPS,true);?><div class="aics-wizard-progress-wrap"><ol class="aics-wizard-progress"><?php foreach(AICS_Setup_Wizard_State_Service::STEPS as $i=>$key):$done=in_array($key,$s['setup_completed_steps'],true);?><li class="<?php echo esc_attr($i===$active?'is-active':($done?'is-complete':'is-pending'));?>"><button type="button" data-aics-step="<?php echo esc_attr($key);?>" <?php disabled(!AICS_Setup_Wizard_State_Service::can_open($key));?> <?php echo $i===$active?'aria-current="step"':'';?>><span><?php echo $done?'✓':esc_html((string)($i+1));?></span><strong><?php echo esc_html($labels[$key]);?></strong></button></li><?php endforeach;?></ol></div><div class="aics-wizard-notice" aria-live="polite"></div><section class="aics-wizard-card" aria-labelledby="aics-setup-step-title"><?php self::step($step,$s);?></section><div class="aics-wizard-live screen-reader-text" aria-live="polite"></div><?php return (string)ob_get_clean();}
	private static function select(string $name,array $values,string $selected):void{?><select name="<?php echo esc_attr($name);?>"><?php foreach($values as $key=>$label):$value=is_int($key)?$label:$key;?><option value="<?php echo esc_attr($value);?>" <?php selected($selected,$value);?>><?php echo esc_html($label);?></option><?php endforeach;?></select><?php }
	private static function step(string $step,array $s):void{$index=array_search($step,AICS_Setup_Wizard_State_Service::STEPS,true);?><form class="aics-wizard-form aics-setup-form"><p class="aics-wizard-eyebrow"><?php echo esc_html(sprintf(__('Step %1$d of %2$d','ai-content-studio'),$index+1,6));?></p><?php if('welcome'===$step):?><h2 id="aics-setup-step-title" tabindex="-1"><?php esc_html_e('Welcome to AI Content Studio','ai-content-studio');?></h2><p><?php esc_html_e('Let’s connect your AI provider and prepare WordPress for content creation and automation.','ai-content-studio');?></p><ul><li><?php esc_html_e('Generate content ideas and articles','ai-content-studio');?></li><li><?php esc_html_e('Create featured images','ai-content-studio');?></li><li><?php esc_html_e('Optimize posts for SEO','ai-content-studio');?></li><li><?php esc_html_e('Review manually or automate publishing','ai-content-studio');?></li></ul><p><?php esc_html_e('Setup usually takes a few minutes.','ai-content-studio');?></p>
		<?php elseif('ai-provider'===$step):?><h2 id="aics-setup-step-title" tabindex="-1"><?php esc_html_e('Connect your AI provider','ai-content-studio');?></h2><div class="aics-field-grid"><label><?php esc_html_e('Text AI Provider','ai-content-studio');?><select disabled><option>OpenAI</option></select></label><label><?php esc_html_e('Model','ai-content-studio'); self::select('openai_model',AICS_Settings::get_allowed_models(),AICS_Settings::get_openai_model());?></label></div><label><?php esc_html_e('API Key','ai-content-studio');?><input type="password" name="openai_api_key" autocomplete="new-password" placeholder="<?php echo esc_attr(AICS_Settings::has_openai_api_key()?__('Saved — leave blank to keep it','ai-content-studio'):__('Enter API key','ai-content-studio'));?>"></label><p class="description"><?php esc_html_e('The saved key is never returned to the browser. Changing the key or model requires a new test.','ai-content-studio');?></p><button class="button" data-aics-operation="test_provider"><?php esc_html_e('Test Connection','ai-content-studio');?></button><?php if(AICS_Setup_Wizard_State_Service::provider_ready()):?><p class="aics-setup-ready">✓ <?php esc_html_e('Connection tested successfully.','ai-content-studio');?></p><?php endif;?>
		<?php elseif('featured-images'===$step):$i=AICS_Featured_Image_Settings::get_effective();$provider=AICS_Image_Provider_Factory::create($i['provider']);$cap=is_wp_error($provider)?array():$provider->get_capabilities();?><h2 id="aics-setup-step-title" tabindex="-1"><?php esc_html_e('Featured Images','ai-content-studio');?></h2><label class="aics-check-row"><input type="checkbox" name="enabled" value="1" <?php checked($i['enabled']);?>> <?php esc_html_e('Enable AI Featured Images','ai-content-studio');?></label><div class="aics-field-grid"><label><?php esc_html_e('Provider','ai-content-studio'); self::select('provider',array('openai'=>'OpenAI'),$i['provider']);?></label><label><?php esc_html_e('Model','ai-content-studio'); self::select('model',$cap['supported_models']??array($i['model']),$i['model']);?></label><label><?php esc_html_e('Visual style','ai-content-studio'); self::select('visual_style',array('editorial','photorealistic','illustration','minimal'),$i['visual_style']);?></label><label><?php esc_html_e('Aspect ratio','ai-content-studio'); self::select('aspect_ratio',$cap['supported_aspect_ratios']??array('landscape','square','portrait'),$i['aspect_ratio']);?></label><label><?php esc_html_e('Quality','ai-content-studio'); self::select('quality',$cap['supported_quality_levels']??array('standard','high'),$i['quality']);?></label><label><?php esc_html_e('Output format','ai-content-studio'); self::select('output_format',$cap['supported_output_formats']??array('png','jpeg','webp'),$i['output_format']);?></label></div><button class="button" data-aics-operation="test_images"><?php esc_html_e('Test Image Generation','ai-content-studio');?></button><p><?php esc_html_e('The test deletes its temporary file and creates no post or Media Library item.','ai-content-studio');?></p>
		<?php elseif('seo-integration'===$step):$det=(new AICS_SEO_Plugin_Detector())->resolve($s['seo_target']);?><h2 id="aics-setup-step-title" tabindex="-1"><?php esc_html_e('SEO Integration','ai-content-studio');?></h2><div class="aics-setup-status-card"><strong><?php esc_html_e('Detected SEO Integration','ai-content-studio');?></strong><p><?php echo esc_html('native'===$det['key']?__('No supported SEO plugin is active. Native WordPress fields will be used.','ai-content-studio'):sprintf(__('%s is active and supported.','ai-content-studio'),AICS_SEO_Configuration::target_labels()[$det['key']]??$det['key']));?></p></div><label><?php esc_html_e('SEO target','ai-content-studio'); self::select('seo_target',AICS_SEO_Configuration::target_labels(),$s['seo_target']);?></label><?php if($det['multiple']):?><p class="aics-setup-warning"><?php esc_html_e('Multiple supported SEO plugins are active. Only one deterministic adapter will be used.','ai-content-studio');?></p><?php endif;?><?php if(!get_option('blog_public')):?><p class="aics-setup-warning"><?php esc_html_e('WordPress discourages search engines on this site. This common staging setting does not block setup.','ai-content-studio');?></p><?php endif;?><p><?php esc_html_e('Supported: SEO title, meta description, focus keyword, slug, excerpt, categories, and tags.','ai-content-studio');?></p>
		<?php elseif('content-defaults'===$step):$d=$s['defaults'];?><h2 id="aics-setup-step-title" tabindex="-1"><?php esc_html_e('Content Defaults','ai-content-studio');?></h2><div class="aics-field-grid"><label><?php esc_html_e('Default Tone','ai-content-studio'); self::select('tone',array('professional','friendly','informative','conversational'),$d['tone']);?></label><label><?php esc_html_e('Default Article Length','ai-content-studio'); self::select('article_length',array('short','medium','long'),$d['article_length']);?></label><label><?php esc_html_e('Default Format','ai-content-studio'); self::select('content_format',array('plain','how-to','listicle'),$d['content_format']);?></label><label><?php esc_html_e('Default WordPress Status','ai-content-studio'); self::select('post_status',array('draft'=>__('Draft','ai-content-studio')),'draft');?></label></div><p><?php esc_html_e('These defaults prefill new Manual Studio sessions. Automations retain their own settings.','ai-content-studio');?></p>
		<?php else:?><h2 id="aics-setup-step-title" tabindex="-1"><?php esc_html_e('Finish Setup','ai-content-studio');?></h2><div class="aics-setup-summary"><div><strong><?php esc_html_e('AI Provider','ai-content-studio');?></strong><span><?php echo AICS_Setup_Wizard_State_Service::provider_ready()?esc_html__('Ready','ai-content-studio'):esc_html__('Action required','ai-content-studio');?></span></div><div><strong><?php esc_html_e('Featured Images','ai-content-studio');?></strong><span><?php echo esc_html(AICS_Featured_Image_Settings::get_effective()['enabled']?__('Enabled','ai-content-studio'):__('Disabled for now','ai-content-studio'));?></span></div><div><strong><?php esc_html_e('SEO','ai-content-studio');?></strong><span><?php echo esc_html(AICS_SEO_Configuration::target_labels()[$s['seo_target']]);?></span></div></div><?php if('completed'===$s['setup_status']):?><div class="aics-setup-finish-actions"><a class="button button-primary" href="<?php echo esc_url(admin_url('admin.php?page=aics-create-content'));?>"><?php esc_html_e('Create Your First Article','ai-content-studio');?></a><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=aics-automations'));?>"><?php esc_html_e('Create an Automation','ai-content-studio');?></a><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=ai-content-studio'));?>"><?php esc_html_e('Open Dashboard','ai-content-studio');?></a><a href="<?php echo esc_url(admin_url('admin.php?page=aics-settings'));?>"><?php esc_html_e('Review Settings','ai-content-studio');?></a><a href="<?php echo esc_url(admin_url('admin.php?page=aics-settings&section=system-status'));?>"><?php esc_html_e('Open System Status','ai-content-studio');?></a></div><?php endif;?><?php endif;?><div class="aics-wizard-actions"><?php if($index>0):?><button type="button" class="button" data-aics-step="<?php echo esc_attr(AICS_Setup_Wizard_State_Service::STEPS[$index-1]);?>"><?php esc_html_e('Back','ai-content-studio');?></button><?php endif;?><?php $actions=array('welcome'=>array('start'=>__('Start Setup','ai-content-studio')),'ai-provider'=>array('continue_provider'=>__('Continue to Featured Images','ai-content-studio')),'featured-images'=>array('save_images'=>__('Save and Continue','ai-content-studio')),'seo-integration'=>array('save_seo'=>__('Continue to Content Defaults','ai-content-studio')),'content-defaults'=>array('save_defaults'=>__('Review Setup','ai-content-studio')),'finish'=>array('complete'=>__('Complete Setup','ai-content-studio')));if('completed'!==$s['setup_status']):foreach($actions[$step] as $op=>$label):?><button class="button button-primary" data-aics-operation="<?php echo esc_attr($op);?>"><?php echo esc_html($label);?></button><?php endforeach;endif;if('welcome'===$step):?><button class="button" data-aics-operation="dismiss"><?php esc_html_e('Skip for Now','ai-content-studio');?></button><?php elseif('featured-images'===$step):?><button class="button" data-aics-operation="skip_images"><?php esc_html_e('Disable Images and Continue','ai-content-studio');?></button><?php elseif('completed'===$s['setup_status']):?><button class="button" data-aics-operation="restart"><?php esc_html_e('Review Setup Again','ai-content-studio');?></button><?php endif;?><a href="<?php echo esc_url(admin_url('admin.php?page=ai-content-studio'));?>"><?php esc_html_e('Exit Setup','ai-content-studio');?></a></div></form><?php }
	private function __construct(){}
}
